"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Calculator, CheckCircle2, EyeOff, LockKeyhole, RefreshCw, ShieldAlert } from "lucide-react";
import {
  createEvaluationAction, declareEvaluationConflictAction, getLatestEvaluationAction,
  recordEvaluationScoreAction, reopenEvaluationScoreAction, setCommercialAccessAction,
  type EvaluationEvidence, type EvaluationView,
} from "@/app/actions/evaluationEngine";

const label = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const verdictStyle: Record<string, string> = { addressed: "bg-emerald-100 text-emerald-800", partially_addressed: "bg-amber-100 text-amber-800", missing: "bg-red-100 text-red-800", contradictory: "bg-red-100 text-red-800", not_applicable: "bg-slate-100 text-slate-700", not_assessable: "bg-sky-100 text-sky-800" };
const money = (amount: number | null, currency: string | null) => amount === null ? "Not provided" : new Intl.NumberFormat("en-US", { style: "currency", currency: currency ?? "USD", maximumFractionDigits: 2 }).format(amount);
const locator = (value: Record<string, string | number>) => Object.entries(value).filter(([key]) => ["page", "sheet", "row", "column"].includes(key)).map(([key, item]) => `${key} ${item}`).join(" · ");

function Evidence({ items }: { items: EvaluationEvidence[] }) {
  if (!items.length) return null;
  return <details className="mt-2"><summary className="cursor-pointer text-[11px] font-bold text-[#0076b4]">View cited evidence ({items.length})</summary><ul className="mt-2 space-y-2">{items.map((item) => <li key={item.fragmentId} className="rounded-lg bg-sky-50 px-3 py-2"><p className="text-[10px] font-bold uppercase text-slate-500">{item.sourceLabel}{locator(item.locator) ? ` · ${locator(item.locator)}` : ""}</p><p className="mt-1 whitespace-pre-wrap text-xs leading-5 text-slate-700">{item.content}</p></li>)}</ul></details>;
}

function ScoreCard({ criterion, assessments, current, assignmentId, conflictClear, saving, onSave, onReopen }: {
  criterion: EvaluationView["criteria"][number]; assessments: EvaluationView["assessments"]; current?: EvaluationView["scores"][number]; assignmentId: string; conflictClear: boolean; saving: boolean;
  onSave: (criterionId: string, eventType: "draft" | "submitted" | "superseded", score: number, rationale: string, citations: string[]) => Promise<void>;
  onReopen: (assignmentId: string, criterionId: string) => Promise<void>;
}) {
  const [score, setScore] = useState(current?.score === null || current?.score === undefined ? "" : String(current.score));
  const [rationale, setRationale] = useState(current?.rationale ?? "");
  const evidence = useMemo(() => assessments.flatMap((assessment) => assessment.evidence).filter((item, index, all) => all.findIndex((candidate) => candidate.fragmentId === item.fragmentId) === index), [assessments]);
  const [citations, setCitations] = useState<string[]>(current?.evidenceFragmentIds ?? []);
  const locked = current?.eventType === "submitted" || current?.eventType === "superseded";
  const afterReopen = current?.eventType === "reopened";
  const valid = score !== "" && Number(score) >= 0 && Number(score) <= criterion.rubricMaximum;
  return <li className="rounded-xl border border-slate-200 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-bold text-slate-800">{criterion.name}</p><p className="mt-1 text-xs text-slate-500">{criterion.description}</p></div><span className="rounded-full bg-violet-100 px-2 py-1 text-[10px] font-bold uppercase text-violet-800">{criterion.weight}% weight · 0–{criterion.rubricMaximum}</span></div>
    {criterion.rubricAnchors.length > 0 && <details className="mt-3 rounded-lg bg-violet-50 px-3 py-2"><summary className="cursor-pointer text-[11px] font-bold text-violet-900">Scoring anchors</summary><dl className="mt-2 grid gap-2 sm:grid-cols-2">{criterion.rubricAnchors.map((anchor) => <div key={anchor.score} className="text-[11px] leading-4 text-violet-950"><dt className="font-bold">{anchor.score} · {anchor.label}</dt><dd className="mt-0.5 text-violet-800">{anchor.description}</dd></div>)}</dl></details>}
    {locked ? <div className="mt-3 rounded-xl bg-emerald-50 p-3"><p className="text-xs font-bold text-emerald-800">Submitted score: {current.score} / {current.rubricMaximum} · contribution {current.weightedContribution?.toFixed(2)} points</p><p className="mt-1 text-xs text-slate-700">{current.rationale}</p><button type="button" disabled={saving} onClick={() => void onReopen(assignmentId, criterion.criterionId)} className="mt-2 text-[11px] font-bold text-[#0076b4]">Reopen for correction</button></div>
    : <div className="mt-3 space-y-3"><div className="grid gap-3 sm:grid-cols-[120px_1fr]"><label className="text-xs font-bold text-slate-600">Score<input aria-label={`${criterion.name} score`} type="number" min="0" max={criterion.rubricMaximum} step="0.5" value={score} onChange={(event) => setScore(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"/></label><label className="text-xs font-bold text-slate-600">Rationale<textarea aria-label={`${criterion.name} rationale`} value={rationale} onChange={(event) => setRationale(event.target.value)} rows={2} className="mt-1 w-full resize-y rounded-lg border border-slate-300 px-3 py-2 text-xs"/></label></div>
      {evidence.length > 0 && <fieldset><legend className="text-[11px] font-bold text-slate-600">Cited evidence</legend><div className="mt-1 space-y-1">{evidence.map((item) => <label key={item.fragmentId} className="flex gap-2 text-[11px] text-slate-600"><input type="checkbox" checked={citations.includes(item.fragmentId)} onChange={(event) => setCitations((currentItems) => event.target.checked ? [...currentItems, item.fragmentId] : currentItems.filter((id) => id !== item.fragmentId))}/><span>{item.sourceLabel}{locator(item.locator) ? ` · ${locator(item.locator)}` : ""}: {item.content.slice(0, 140)}</span></label>)}</div></fieldset>}
      <div className="flex flex-wrap gap-2"><button type="button" disabled={saving || !valid} onClick={() => void onSave(criterion.criterionId, "draft", Number(score), rationale, citations)} className="rounded-lg border border-slate-300 px-3 py-2 text-[11px] font-bold text-slate-700 disabled:opacity-50">Save draft</button><button type="button" disabled={saving || !valid || !conflictClear || !rationale.trim() || (!criterion.humanOnly && citations.length === 0)} onClick={() => void onSave(criterion.criterionId, afterReopen ? "superseded" : "submitted", Number(score), rationale, citations)} className="rounded-lg bg-[#087f69] px-3 py-2 text-[11px] font-bold text-white disabled:opacity-50">Submit score</button></div>
      {!conflictClear && <p className="text-[11px] text-amber-700">Declare your conflict-of-interest status before submitting.</p>}
    </div>}
    {assessments.length > 0 && <details className="mt-3"><summary className="cursor-pointer text-[11px] font-bold text-[#0076b4]">Relevant requirement assessments ({assessments.length})</summary><ul className="mt-2 space-y-2">{assessments.map((assessment) => <li key={assessment.assessmentId} className="rounded-lg bg-slate-50 p-2 text-xs"><span className={`rounded-full px-2 py-0.5 text-[9px] font-bold uppercase ${verdictStyle[assessment.verdict]}`}>{label(assessment.verdict)}</span><p className="mt-1 font-semibold text-slate-700">{assessment.requirementTitle}</p><Evidence items={assessment.evidence}/></li>)}</ul></details>}
  </li>;
}

export default function VendorEvaluationSection({ proposalId, submissionId, versionId }: { proposalId: string; submissionId: string; versionId: string }) {
  const [view, setView] = useState<EvaluationView>(); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState<string>(); const [tab, setTab] = useState<"assessments" | "risks" | "commercial" | "scorecard">("assessments"); const [sealed, setSealed] = useState(false); const cancelled = useRef(false);
  const load = useCallback(async () => { const response = await getLatestEvaluationAction(proposalId, submissionId, versionId); if (cancelled.current) return; setLoading(false); if (response.success) { setView(response.data); setError(undefined); } else if (response.code === "EVALUATION_RUN_NOT_FOUND") { setView(undefined); setError(undefined); } else setError(response.message); }, [proposalId, submissionId, versionId]);
  useEffect(() => { cancelled.current = false; const timer = window.setTimeout(() => void load(), 0); return () => { cancelled.current = true; window.clearTimeout(timer); }; }, [load]);
  const mutate = async (operation: () => Promise<{ success: boolean; message?: string }>) => { setBusy(true); setError(undefined); const response = await operation(); if (cancelled.current) return; setBusy(false); if (!response.success) { setError(response.message ?? "Evaluation operation failed."); return; } await load(); };
  const create = () => mutate(() => createEvaluationAction(proposalId, submissionId, versionId, sealed));
  const conflict = (status: "clear" | "conflict") => view?.assignment ? mutate(() => declareEvaluationConflictAction(proposalId, submissionId, versionId, view.run.runId, status, status === "conflict" ? "Evaluator disclosed a potential conflict for owner review." : "", view.assignment!.version)) : Promise.resolve();
  const saveScore = (criterionId: string, eventType: "draft" | "submitted" | "superseded", score: number, rationale: string, evidenceFragmentIds: string[]) => view ? mutate(() => recordEvaluationScoreAction(proposalId, submissionId, versionId, view.run.runId, { criterionId, eventType, score, rationale, evidenceFragmentIds })) : Promise.resolve();
  const reopen = (assignmentId: string, criterionId: string) => view ? mutate(() => reopenEvaluationScoreAction(proposalId, submissionId, versionId, view.run.runId, assignmentId, criterionId, "Correction requested by the proposal owner.")) : Promise.resolve();
  const grantSelf = () => view?.assignment ? mutate(() => setCommercialAccessAction(proposalId, submissionId, versionId, view.run.runId, view.assignment!.assignmentId, "granted", "Commercial access granted for assigned evaluation.")) : Promise.resolve();
  const scores = new Map(view?.scores.map((score) => [score.criterionId, score]));
  return <section className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm" aria-labelledby="evaluation-title"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 id="evaluation-title" className="flex items-center gap-2 text-sm font-bold text-slate-900"><Calculator size={17} className="text-[#008ad2]"/>Human evaluation</h3><p className="mt-1 max-w-2xl text-xs leading-5 text-slate-500">Score this response against your criteria. Only scores submitted by people count toward the result.</p></div>{!view && <button type="button" disabled={busy || loading} onClick={() => void create()} className="inline-flex min-h-9 items-center gap-2 rounded-xl bg-[#087f69] px-3.5 text-xs font-bold text-white disabled:opacity-50"><RefreshCw size={13} className={busy ? "animate-spin" : ""}/>{busy ? "Preparing…" : "Start evaluation"}</button>}</div>
    {!view && !loading && <label className="mt-3 flex items-center gap-2 text-xs text-slate-600"><input type="checkbox" checked={sealed} onChange={(event) => setSealed(event.target.checked)}/>Seal commercial values until access is explicitly granted</label>}
    {error && <p role="alert" className="mt-4 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-800">{error}</p>}{loading && <p className="mt-4 text-xs text-slate-500">Checking evaluation status…</p>}{!view && !loading && !error && <p className="mt-4 rounded-xl bg-slate-50 px-4 py-3 text-xs text-slate-600">No evaluation has been started yet. Run the AI analysis and approve your requirement checklist first.</p>}
    {view && <>{view.assignment && view.assignment.role !== "observer" && <div className="mt-4 flex flex-wrap items-center gap-2 rounded-xl bg-slate-50 p-3"><span className="text-xs font-bold text-slate-700">Conflict declaration:</span><button type="button" disabled={busy} onClick={() => void conflict("clear")} className={`rounded-lg px-2.5 py-1.5 text-[11px] font-bold ${view.assignment.conflictStatus === "clear" ? "bg-emerald-600 text-white" : "border border-emerald-200 text-emerald-700"}`}><CheckCircle2 size={12} className="mr-1 inline"/>No conflict</button><button type="button" disabled={busy} onClick={() => void conflict("conflict")} className={`rounded-lg px-2.5 py-1.5 text-[11px] font-bold ${view.assignment.conflictStatus === "conflict" ? "bg-amber-600 text-white" : "border border-amber-200 text-amber-700"}`}><ShieldAlert size={12} className="mr-1 inline"/>Disclose conflict</button></div>}
      <div className="mt-4 flex gap-1 overflow-x-auto border-b border-slate-200">{(["assessments", "risks", "commercial", "scorecard"] as const).map((item) => <button key={item} type="button" onClick={() => setTab(item)} className={`whitespace-nowrap border-b-2 px-3 py-2 text-xs font-bold ${tab === item ? "border-[#008ad2] text-[#0076b4]" : "border-transparent text-slate-500"}`}>{label(item)}</button>)}</div>
      {tab === "assessments" && <ul className="mt-3 space-y-3">{view.assessments.map((item) => <li key={item.assessmentId} className="rounded-xl border border-slate-200 p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="text-sm font-bold text-slate-800">{item.requirementTitle}</p><p className="mt-1 text-xs leading-5 text-slate-600">{item.rationale}</p></div><span className={`h-fit rounded-full px-2 py-1 text-[10px] font-bold uppercase ${verdictStyle[item.verdict]}`}>{label(item.verdict)}</span></div><p className="mt-2 text-[10px] uppercase text-slate-400">{item.mandatory ? "Mandatory · " : ""}{Math.round(item.confidence * 100)}% extraction confidence{item.needsHumanReview ? " · Review required" : ""}</p><Evidence items={item.evidence}/></li>)}</ul>}
      {tab === "risks" && <ul className="mt-3 space-y-3">{view.risks.map((risk) => <li key={risk.riskId} className={`rounded-xl border p-4 ${risk.severity === "high" ? "border-red-200 bg-red-50/40" : risk.severity === "medium" ? "border-amber-200 bg-amber-50/30" : "border-slate-200"}`}><p className="text-[10px] font-bold uppercase text-slate-500">{risk.severity} · {label(risk.category)}</p><p className="mt-1 text-sm font-bold text-slate-800">{risk.title}</p><p className="mt-1 text-xs leading-5 text-slate-600">{risk.basis}</p><p className="mt-2 rounded-lg bg-white/80 p-2 text-xs text-slate-700"><strong>Clarification candidate:</strong> {risk.question}</p><Evidence items={risk.evidence}/></li>)}</ul>}
      {tab === "commercial" && <div className="mt-3">{!view.permission.canViewCommercial ? <div className="rounded-xl border border-slate-200 bg-slate-50 p-5 text-center"><EyeOff className="mx-auto text-slate-400"/><p className="mt-2 text-sm font-bold text-slate-700">Commercial values are sealed</p><p className="mt-1 text-xs text-slate-500">An explicit access event is required; hidden values are not returned to this view.</p>{view.permission.owner && view.assignment && <button type="button" disabled={busy} onClick={() => void grantSelf()} className="mt-3 rounded-lg bg-[#087f69] px-3 py-2 text-xs font-bold text-white">Grant my assignment access</button>}</div> : view.commercial ? <><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-slate-200 p-4"><p className="text-[10px] font-bold uppercase text-slate-400">Submitted total</p><p className="mt-1 text-xl font-extrabold text-slate-800">{money(view.commercial.submittedTotal, view.commercial.submittedCurrency)}</p><p className="mt-1 text-xs text-slate-500">Vendor-stated value, preserved unchanged.</p></div><div className={`rounded-xl border p-4 ${view.commercial.comparable ? "border-emerald-200 bg-emerald-50/30" : "border-amber-200 bg-amber-50/30"}`}><p className="text-[10px] font-bold uppercase text-slate-400">Normalized comparison total</p><p className="mt-1 text-xl font-extrabold text-slate-800">{view.commercial.comparable ? money(view.commercial.normalizedTotal, view.commercial.normalizedCurrency) : "Not comparable"}</p><p className="mt-1 text-xs text-slate-500">{view.commercial.comparable ? "Identity normalization only; no adjustment applied." : `Refused: ${view.commercial.refusalCodes.map(label).join(", ")}`}</p></div></div><ul className="mt-3 space-y-2">{view.commercial.lineItems.map((item, index) => <li key={`${item.category}-${index}`} className="rounded-lg border border-slate-200 px-3 py-2"><p className="text-xs font-semibold text-slate-700">{item.description}</p><p className="text-[10px] uppercase text-slate-400">{label(item.category)}{item.amount !== null ? ` · ${money(item.amount, item.currency)}` : ""}{item.optionOrExclusion ? " · option/exclusion" : ""}</p></li>)}</ul></> : <p className="rounded-xl bg-slate-50 p-4 text-xs text-slate-600">No commercial record is available.</p>}</div>}
      {tab === "scorecard" && view.assignment && (view.assignment.role === "observer" ? <div className="mt-3 rounded-xl border border-slate-200 bg-slate-50 p-4"><p className="text-sm font-bold text-slate-800">Observer assignment is read-only</p><p className="mt-1 text-xs text-slate-600">You can inspect assessments, risks, commercial information you are authorized to view, and submitted score summaries. Observer input never contributes to vendor totals.</p></div> : <>{view.assignment.complete && view.assignment.overallScore !== null && <div className="mt-3 rounded-xl bg-emerald-50 p-4"><p className="text-[10px] font-bold uppercase text-emerald-700">Completed human evaluator score</p><p className="mt-1 text-2xl font-extrabold text-emerald-900">{view.assignment.overallScore.toFixed(2)} / 100</p></div>}{view.permission.owner && view.aggregates.length > 0 && <div className="mt-3 grid gap-2 sm:grid-cols-2">{view.aggregates.map((aggregate) => { const criterion = view.criteria.find((item) => item.criterionId === aggregate.criterionId); return <div key={aggregate.criterionId} className="rounded-xl bg-violet-50 p-3"><p className="text-xs font-bold text-violet-900">{criterion?.name ?? "Criterion"}</p><p className="mt-1 text-[11px] text-violet-700">{aggregate.submittedCount}/{aggregate.assignedCount} submitted{aggregate.mean === null ? " · aggregation incomplete" : ` · mean ${aggregate.mean.toFixed(2)} · spread ${aggregate.spread?.toFixed(2) ?? "0.00"}`}</p></div>; })}</div>}<p className="mt-3 flex items-center gap-2 text-xs text-slate-500"><LockKeyhole size={13}/>Submitted scores are locked. To correct one, reopen it — the change is tracked.</p><ul className="mt-3 space-y-3">{view.criteria.filter((criterion) => view.assignment!.criterionIds.includes(criterion.criterionId)).map((criterion) => <ScoreCard key={`${criterion.criterionId}:${scores.get(criterion.criterionId)?.eventId ?? "new"}`} criterion={criterion} assessments={view.assessments.filter((assessment) => criterion.requirementIds.includes(assessment.requirementId))} current={scores.get(criterion.criterionId)} assignmentId={view.assignment!.assignmentId} conflictClear={view.assignment!.conflictStatus === "clear"} saving={busy} onSave={saveScore} onReopen={reopen}/>)}</ul></>)}
    </>}</section>;
}
